urlset:

{% for url in static_urls %}

  {{ origin }}{{ url.url }}
  {{ url.changefreq }}
  {{ url.priority }}

{% endfor %}


{% for listing in listings %}

  {{ origin }}/listings/{{ listing.slug }}/
  {% if listing.list_date %}{{ listing.list_date|date:'c' }}{% endif %}
  weekly
  0.7
  {% if listing.image_url %}

    {{ origin }}{{ listing.image_url }}
    {{ listing.title|escape }}

  {% endif %}

{% endfor %}


{% for service in services %}

  {{ origin }}/services/{{ service.slug }}/
  {% if service.updated_at %}{{ service.updated_at|date:'c' }}{% endif %}
  monthly
  0.6

{% endfor %}


{% for blog in blogs %}

  {{ origin }}/blog/{{ blog.slug }}/
  {% if blog.posted_at %}{{ blog.posted_at|date:'c' }}{% endif %}
  monthly
  0.5

{% endfor %}


{% for legal in legal_entries %}

  {{ origin }}{{ legal.url }}
  {% if legal.last_modified %}{{ legal.last_modified|date:'c' }}{% endif %}
  yearly
  0.3

{% endfor %}


{% for custom in custom_urls %}

  {{ origin }}{{ custom.url }}
  {% if custom.last_modified %}{{ custom.last_modified|date:'c' }}{% endif %}
  {{ custom.changefreq }}
  {{ custom.priority }}

{% endfor %}
